"""The journey's breeding web as a page: python3 -I breeding/studbook_report.py -> docs/BREEDING_LAB.md"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ENGINE = os.path.dirname(HERE)
sys.path.insert(0, ENGINE)

from battle.scouting import GAME_TITLE  # noqa: E402
from breeding.studbook import Studbook  # noqa: E402

OUT = os.path.join(os.path.dirname(ENGINE), "docs", "BREEDING_LAB.md")
INTRO = """# The Breeding Lab: the journey as one family tree

*Generated by `breeding/studbook_report.py` from the canon (rosters, builds, the ranch program). Decision D-044.*

The journey is over and every companion is retired (D-042). What the Champion does now is breed: tinker with
builds, chase movesets, and raise stock that can go different ways. The rule: **every Pokémon of the journey is
a parent of breeding stock or a product of it**, and the lab works for Pokémon outside the journey too.

The lab runs on the ranch era's rules: Gen 4 (HGSS and Platinum), with Gen 3 moves arriving by Pal Park.
Genders aren't decided yet, so "father" and "mother" mean *could be*. Only egg moves the target line can't learn
by itself are counted, and only ones worth breeding for (a 60+ power attack, priority, or a strategic tool).
"""


def main():
    book = Studbook(os.path.join(ENGINE, "data", "pokeref.sqlite"))
    roles = book.roles()
    lines = [INTRO, "## Every companion's place in the family tree", "",
             "| Companion | Roles | Bred with (egg-only moves on its build) | Can father (notable) |", "|---|---|---|---|"]
    for e in roles:
        game, sp = e["companion"].split(":")
        bred = []
        for mv, fathers in e["bred_moves"].items():
            chains = e["journey_chains"].get(mv, [])
            src = (f"from {', '.join(fathers)}" if fathers else f"journey chain {', '.join(chains)}" if chains
                   else "needs a father from outside the journey")
            bred.append(f"**{mv}** ({src})")
        sires = "; ".join(f"{t}: {', '.join(m)}" for t, m in list(e["as_father"].items())[:4])
        more = len(e["as_father"]) - 4
        lines.append(f"| {GAME_TITLE[game]} {sp} | {', '.join(e['roles'])} | {'; '.join(bred) or '—'} | "
                     f"{sires or '—'}{f' (+{more} more lines)' if more > 0 else ''} |")
    lines += ["", "## Chains that never leave the journey", ""]
    for e in roles:
        for mv, chains in e["journey_chains"].items():
            if chains:
                lines.append(f"- **{e['species']} · {mv}:** " + "; ".join(f"{c} → {e['species']}" for c in chains))
    lines += ["", "## Best fathers in the journey (notable egg moves they can pass)", "",
              "| Father | Moves passed | Lines reached |", "|---|---|---|"]
    for f, n, t in book.leaderboard()[:10]:
        lines.append(f"| {f} | {n} | {t} |")
    lines += ["", "## The tinkering menu", "",
              "For companions whose build has no egg-only move yet: the egg moves their line could carry, and which "
              "journey fathers could give each one (— means a father from outside the journey).", ""]
    for e in roles:
        menu = e.get("tinker_menu")
        if menu:
            game, sp = e["companion"].split(":")
            lines.append(f"- **{GAME_TITLE[game]} {sp}:** " + "; ".join(
                f"{mv} ({', '.join(f) if f else '—'})" for mv, f in list(menu.items())[:8]))
    with open(OUT, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")
    print("wrote", OUT)


if __name__ == "__main__":
    main()
